[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$ContractPath,[Parameter(Mandatory=$true)][string]$FixturePath)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$c=(Resolve-Path $ContractPath).Path;$f=(Resolve-Path $FixturePath).Path;if(-not $c.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)-or -not $f.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'Paths must remain under project root.'};$x=Get-Content $c -Raw -Encoding UTF8|ConvertFrom-Json;$issues=[Collections.Generic.List[string]]::new();if($x.mode -ne 'local-adapter'){$issues.Add('MODE_NOT_LOCAL_ADAPTER')};if($x.network.enabled){$issues.Add('NETWORK_ENABLED')};if($x.execution.status -ne 'not-run' -or $x.execution.networkCalls -ne 0){$issues.Add('CONTRACT_EXECUTION_NOT_RUN')};$o=[ordered]@{validator='web-local-adapter';status=if($issues.Count){'blocked'}else{'passed'};findingCount=$issues.Count;findings=@($issues);runtimeStatus='runtime-not-run';nonClaims=@('Static local-adapter validation does not execute network')};$o|ConvertTo-Json -Depth 8;if($issues.Count){exit 1}
